  // unchanged (not the aggregated BadRequest).
  @AggregateParamErrors()
  @UseFilters(MyWideFilter)
  @Get('wide/:id')
  public wide(
    @Param('id', new NotFoundPipe()) id: string,
    @Query('limit', new NumberPipe('B')) limit: number,
  ) {
    recordHandler('wide');
    return `${id},${limit}`;
  }
}

