import {
  AggregateParamErrors,
  BadRequestException,
  Controller,
  Get,
  Headers,
  INestApplication,
  Param,
  PipeTransform,
  Query,
} from '@nestjs/common';
import { Test } from '@nestjs/testing';
import request from 'supertest';

class NumberPipe implements PipeTransform<string, number> {
  constructor(private readonly tag: string) {}
  transform(value: string): number {
    const parsed = Number(value);
    if (Number.isNaN(parsed)) {
      throw new BadRequestException(this.tag);
    }
    return parsed;
  }
}

class HeaderTokenPipe implements PipeTransform<string, string> {
  transform(value: string): string {
    if (value !== 'valid') {
      throw new BadRequestException('H');
    }
    return `token:${value}`;
  }
}

@Controller('p')
class DebugController {
  @AggregateParamErrors()
  @Get('headers/:id')
  public withHeaders(
    @Param('id', new NumberPipe('A')) id: number,
    @Query('limit', new NumberPipe('B')) limit: number,
    @Headers('x-token', new HeaderTokenPipe()) token: string,
  ) {
    return `${id},${limit},${token}`;
  }
}

describe('debug headers', () => {
  let app: INestApplication;
  beforeEach(async () => {
    const moduleRef = await Test.createTestingModule({
      controllers: [DebugController],
    }).compile();
    app = moduleRef.createNestApplication();
    await app.init();
  });
  afterEach(async () => {
    await app.close();
  });

  it('runs the header pipe', async () => {
    const res = await request(app.getHttpServer())
      .get('/p/headers/7?limit=10')
      .set('x-token', 'valid');
    console.log('STATUS', res.status, 'BODY', res.text);
    expect(res.text).toBe('7,10,token:valid');
  });
});

